select
orders.*,
recycle.nick_name,
recycle.tel,
users.name,
users.head_img
from orders orders
left join recycle recycle on orders.recycle_id = recycle.id
left join users users on orders.user_id = users.id

    and orders.id = #{id}
    and orders.order_no = #{orderNo}
    and orders.user_id = #{userId}
    and orders.sub_time_start = #{subTimeStart}
    and orders.sub_time_end = #{subTimeEnd}
    and orders.info = #{info}
    and orders.recycle_id = #{recycleId}
    and orders.status = #{status}
    and orders.create_time = #{createTime}
    and orders.address = #{address}
    and orders.phone like concat('%',#{phone},'%')
    and recycle.nick_name like concat('%',#{nickName},'%')
    and recycle.tel like concat('%',#{tel},'%')
    and users.name like concat('%',#{name},'%')
    and users.head_img = #{headImg}

order by id desc

    limit #{current},#{pageSize}

